class Solution {
  public int connectTwoGroups(List<List<Integer>> cost) {
    int n = cost.size(), m = cost.get(0).size(), full = (1 << m) - 1;
    final int INF = Integer.MAX_VALUE / 4;
    int[] dp =
        new int[1 << m]; // dp[mask]: cheapest way where the right points in mask are connected
    Arrays.fill(dp, INF);
    dp[0] = 0;
    for (int i = 0; i < n; i++) {
      int[] next = new int[1 << m];
      Arrays.fill(next, INF);
      for (int mask = 0; mask <= full; mask++) {
        if (dp[mask] == INF && next[mask] == INF) continue;
        for (int j = 0; j < m; j++) {
          int updated = mask | (1 << j), c = cost.get(i).get(j);
          // first edge of this left point, or one more edge for it
          if (dp[mask] != INF) next[updated] = Math.min(next[updated], dp[mask] + c);
          if (next[mask] != INF) next[updated] = Math.min(next[updated], next[mask] + c);
        }
      }
      dp = next;
    }
    return dp[full];
  }
}
